('b1000000-0000-0000-0000-000000000004', '파친코', '이민진', '일제강점기부터 이어지는 재일교포 4대의 삶을 그린 대하소설.', '인플루엔셜', '2022-04-24', '9791100000045', 'NOVEL', 4, 3.0, false, NOW() - INTERVAL '129 days', NOW() - INTERVAL '129 days'),
('b1000000-0000-0000-0000-000000000005', '데미안', '헤르만 헤세', '싱클레어가 데미안을 만나 자기 자신에게 이르는 길을 찾아가는 성장 소설의 고전.', '민음사', '2000-07-13', '9791100000052', 'NOVEL', 6, 4.5, false, NOW() - INTERVAL '152 days', NOW() - INTERVAL '152 days'),
('b1000000-0000-0000-0000-000000000006', '1984', '조지 오웰', '전체주의 감시 사회를 그린 디스토피아 문학의 걸작.', '민음사', '2003-10-10', '9791100000069', 'NOVEL', 6, 3.7, false, NOW() - INTERVAL '100 days', NOW() - INTERVAL '100 days'),
