-- ===================== 전체 테이블 초기화 =====================
-- CASCADE 로 FK 순서 신경 쓸 필요 없이 한 번에 비운다. (스키마는 유지)
TRUNCATE tb_notifications, tb_review_likes, tb_comments,
         tb_book_rankings, tb_review_rankings, tb_user_rankings,
         tb_refresh_token, tb_binary_content,
         tb_reviews, tb_books, tb_users CASCADE;

